/// QR generated by the Payswiff SDK.
class QrInfo {
  final String qrString;
  final String qrImage; // base64 PNG
  final String? orderId;
  final String? vpa;
  final String? businessName;
  final int? timerSeconds;

  QrInfo({
    required this.qrString,
    required this.qrImage,
    this.orderId,
    this.vpa,
    this.businessName,
    this.timerSeconds,
  });

  factory QrInfo.fromMap(Map map) => QrInfo(
        qrString: map['qrString']?.toString() ?? '',
        qrImage: map['qrImage']?.toString() ?? '',
        orderId: map['orderId']?.toString(),
        vpa: map['vpa']?.toString(),
        businessName: map['businessName']?.toString(),
        timerSeconds: int.tryParse(map['qrTimer']?.toString() ?? ''),
      );
}

/// Final result of a QR payment.
class QrPaymentResult {
  /// success / failed / error / cancelled / expired
  final String status;
  final String? responseCode;
  final String? responseMessage;
  final String? transactionRefNo; // -> sent as transaction_id
  final String? orderId;
  final String? amount;
  final String? transactionDate;

  QrPaymentResult({
    required this.status,
    this.responseCode,
    this.responseMessage,
    this.transactionRefNo,
    this.orderId,
    this.amount,
    this.transactionDate,
  });

  bool get isApproved => status == 'success';

  factory QrPaymentResult.fromMap(Map map) {
    String? s(String k) => map[k]?.toString();
    return QrPaymentResult(
      status: s('status') ?? 'error',
      responseCode: s('responseCode'),
      responseMessage: s('responseMessage'),
      transactionRefNo: s('transactionRefNo'),
      orderId: s('orderId'),
      amount: s('amount'),
      transactionDate: s('transactionDate'),
    );
  }

  factory QrPaymentResult.of(String status, String message) =>
      QrPaymentResult(status: status, responseMessage: message);
}